USE INTEGRACAO;
SET NOCOUNT ON;

-- Unidades com bloqueio automatico. O CID de cada uma fica na variavel de ambiente CNN_CID_<Codigo>.
SELECT IdUnidade, Codigo, Nome
FROM dbo.CtlCnnUnidade
WHERE Ativa = 1
ORDER BY IdUnidade;

